layer.css:
[data-ryt="pitch"] { color: rgb(105, 118, 129); border-left: 4px solid var(--ryt-border); border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(105, 118, 129); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 16px; padding-bottom: 0px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 6px; transition: border-color 0.2s }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-header-text); border-radius: 0px; font-size: 22px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 0px; font-size: 14px; font-weight: 400; font-style: normal; line-height: 4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="button"] { color: rgb(172, 179, 186); background-color: rgb(233, 234, 237); border-top: 1px solid rgb(230, 235, 238); border-right: 1px solid rgb(230, 235, 238); border-bottom: 1px solid rgb(230, 235, 238); border-left: 1px solid rgb(230, 235, 238); border-radius: 8px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(172, 179, 186); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 6px; padding-right: 12px; padding-bottom: 6px; padding-left: 12px; transition: color 0.2s, border-color 0.2s }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; line-height: 1.714; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: #808992; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(139, 148, 158); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #808992; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.714; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(139, 148, 158); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-header-text); border-radius: 0px; font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: light-dark(rgb(41, 131, 187), var(--ryt-bg)) }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { color: light-dark(rgb(41, 131, 187), var(--ryt-bg)); color: light-dark(rgb(234, 81, 127), var(--ryt-bg)) }
[data-ryt="button"]:hover { color: light-dark(#1f2328, #b3bdcb) }
[data-ryt="nav"] a:hover { color: light-dark(rgb(41, 131, 187), var(--ryt-bg)) }
[data-ryt="header"]:hover { box-shadow: light-dark(rgba(0, 0, 0, 0.125), color-mix(in srgb, var(--ryt-bg) 13%, transparent)) 0px 0px 1.5rem }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: light-dark(rgb(41, 131, 187), var(--ryt-bg)); color: light-dark(rgb(234, 81, 127), rgb(204, 85, 149)) }
[data-ryt="footer"]::before { content: ""; display: block; width: 100%; height: 1px; color: var(--ryt-text); background-image: linear-gradient(to right, rgba(0, 0, 0, 0), var(--ryt-border), rgba(0, 0, 0, 0)); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text) }
